  "op.gifCompose.name": "GIF 합성",
  "op.img2dataURI.name": "이미지 → Base64/dataURI",
  "op.imageCompress.desc": "이미지 재인코딩 압축: 품질 0-100 + 선택적 최대 너비(최근접 축소) + JPEG/PNG/WebP 출력 형식. JPEG/WebP는 브라우저 canvas로 인코딩하며 PNG는 모든 환경에서 사용 가능합니다. 미리보기 + 다운로드",
  "op.imageGray.desc": "그레이스케일화(Rec.601: 0.299R+0.587G+0.114B, Pillow 'L' 모드와 동일 공식으로 픽셀 단위 일치) 또는 임계값 이진화(0-255). CTF에서는 컬러 이미지를 평탄화하면 비트 플레인이나 패턴 단서가 드러나는 경우가 많습니다",
  "op.imagePixelate.desc": "모자이크 블록 평균: 블록 크기마다 내부 픽셀의 평균값을 취합니다(가장자리의 불완전 블록은 실제 면적으로 축소 평균). 블록 크기 1-512",
  "op.imageFrosted.desc": "박스 블러: 가로 + 세로 2패스 분리 합성곱으로 가우시안을 근사하며, 가장자리 창은 실제 픽셀로 축소 평균합니다. 반경 1-20",
  "op.imageSketch.desc": "연필 스케치 2모드: dodge＝그레이스케일 반전을 박스 블러한 뒤 컬러 닷지로 혼합(고전 기법); edge＝Sobel 연산자 윤곽 추출(흰 배경에 검은 선)",
  "op.imageToText.desc": "휘도→문자 그라데이션 매핑 아스키 아트: 출력 열 수 20-400 조절 가능(세로 스텝은 가로의 2배), 3종 그라데이션 표(classic/blocks/bits) + 반전. 일반 텍스트로 출력",
  "op.gifCompose.desc": "여러 이미지를 GIF89a로 합성: 첫 프레임 기준 크기 통일(scale/pad) + 프레임 지연 + 반복 횟수. LZW 압축과 NETSCAPE2.0 반복 확장을 직접 구현하고 중위수 분할법으로 256색 이하로 양자화합니다. GIF 다중 프레임 추출의 역방향을 완성",
  "op.img2dataURI.desc": "이미지 → Base64 생성 방향: 이미지를 끌어다 놓으면 파일 헤더로 MIME를 판별하고(PNG/JPG/GIF/BMP/WebP/ICO) dataURI 또는 순수 base64 문자열을 출력",
  "ui.plugin.mcpHowTitle": "사용 방법(로컬 stdio 방식)",
  "ui.plugin.mcpHowIntro": "이 툴박스의 MCP는 로컬 stdio 서비스입니다. AI 클라이언트가 설정에 따라 로컬 프로세스를 직접 실행하며, 설정에 URL이 없는 것이 정상입니다. 완전 로컬·오프라인 사용·외부 전송 없음.",
  "ui.plugin.mcpHowStep1": "이 툴박스 설치 폴더에서 실행: py 通用点我启动.py --mcp-config — 이 PC의 절대 경로가 채워진 연결 설정 JSON이 출력됩니다",
  "ui.plugin.mcpHowStep2": "출력된 mcpServers JSON을 그대로 AI 클라이언트 설정에 넣으세요",
  "ui.plugin.mcpHowStep3": "클라이언트를 재시작한 뒤 도구 목록에 ebctf_* 도구 6개가 나타나면 연결 성공입니다",
  "ui.plugin.mcpHowClients": "설정 파일 위치: Claude Code＝프로젝트 루트 .mcp.json; Cursor＝.cursor/mcp.json(또는 설정의 MCP 패널); Trae＝MCP 설정 패널; Codex / Cline＝각자의 MCP 설정; Claude Desktop＝claude_desktop_config.json",
  "ui.plugin.mcpPromptTitle": "최소 프롬프트(어떤 AI에 붙여도 연결이 완료됩니다)",
  "ui.plugin.mcpPromptPathPh": "설치 경로(선택: 입력하면 더 정확, 비우면 AI가 직접 찾습니다)",
  "ui.plugin.mcpPromptCopy": "최소 프롬프트 복사",
  "ui.plugin.mcpPromptCopied": "복사됨. AI 클라이언트에 붙여넣으세요",
  "ui.plugin.mcpPromptHead": "「恒烈CTF编码工具箱」을 당신의 MCP에 연결하세요:",
  "ui.plugin.mcpPromptDirFilled": "1) 이 PC의 설치 경로: {0}",
  "ui.plugin.mcpPromptDirAuto": "1) 먼저 이 PC에서 설치 경로를 찾으세요(단서: 通用点我启动.py와 mcp/server.mjs가 같은 폴더에 있습니다. 찾을 수 없거나 여러 개면 저에게 물어보세요)",
  "ui.plugin.mcpPromptRest": "2) 그 폴더에서 `py 通用点我启动.py --mcp-config`를 실행하고, 출력의 mcpServers JSON을 그대로 MCP 설정(.mcp.json / claude_desktop_config.json 등)에 넣으세요. 재시작 후 ebctf_* 도구 6개가 나타나야 합니다.\n3) 이것은 로컬 stdio 서비스로, 완전 로컬·외부 전송 없음입니다.\n도구 빠른 안내: ebctf_list_categories 는 전체 분류 목록｜ebctf_list_ops 는 키워드/분류로 알고리즘 목록｜ebctf_op_schema 는 파라미터 schema 조회｜ebctf_detect 는 인코딩 스마트 인식｜ebctf_run_op 는 지정 알고리즘 실행｜ebctf_magic_decode 는 원클릭 스마트 디코딩(다중 체인 지원).",
  "ui.rand.externalNote": "이 op의 난수는 함께 포함된 서드파티 라이브러리({0})가 라이브러리 내부에서 생성하므로 통합 난수원을 거치지 않으며 「암호 강도 강화」의 제어 대상이 아닙니다.",
  "ui.rand.off": "꺼짐(시스템 난수원 crypto.getRandomValues 사용).",
  "ui.rand.mouseAux": "마우스 엔트로피 추가",
  "ui.rand.mouseAuxDesc": "대화 상자에서 마우스를 흔들어 로컬 엔트로피를 수집해 현재 모드에 더합니다(늘기만 하고 줄지 않으며 결과는 원래 모드보다 약해지지 않습니다). 신뢰할 수 없는 시스템용: 시스템 난수원을 단일 실패점으로 두지 않기 위해서입니다.",
