  "op.caesar.desc": "지정한 시프트 값으로 변환(encode +shift, decode -shift). 모드에서 점증/점감 카이사르(x번째 문자를 shift±x만큼 이동)로 전환할 수 있으며, 문자 집합은 영문자만 이동하거나 인쇄 가능 ASCII 33-126 전체 문자 이동(비문자도 움직이는 변형용) 중 선택합니다",
  "op.spriteSheet.name": "스프라이트 시트 변환",
  "op.spriteSheet.desc": "스프라이트 시트 ↔ 프레임 시퀀스 변환: split은 N열 × M행 그리드를 프레임별 PNG로 분할(행 우선, frame_000부터). merge는 여러 프레임(첫 프레임은 메인 입력, 추가 칸에 한 줄당 dataURL 하나)을 행당 프레임 수에 따라 그리드로 합성하며, 마지막 행 빈칸은 투명하게 채웁니다. 순수 JS PNG로 전 환경 사용 가능",
